import {t,copy} from '../strings.js';
import {truthBadge,esc} from '../outpost-presentation.js';
import {accessPreferences,readyVoices,containPoint,makeUtterances} from '../compat.js';
import {COMMANDS,DRIVE_LEVELS,SAMPLE_ROCKS,GEO_ROUNDS,createCommands,addCommand,removeCommand,moveCommand,testDrive,sendDrive,tickDrive,editDrive,nextDrive,commandsResult,createGeology,inspectRock,keepRock,leaveRock,submitGeology,nextGeology,geologyResult} from './field-engine.js';
import {drawField,drawDrive,rockPositions} from './field-art.js';
const commandName=id=>t('command'+id[0].toUpperCase()+id.slice(1));
const sampleName=id=>t(copy('sampleRocks')[id].name);
export function openFieldTraining(id,{onFinish=()=>{},onClose=()=>{}}={}){
 const state=id==='commands'?createCommands():createGeology(),prefs=accessPreferences();let voice=prefs.voice!==false,view='intro',previousView='play',closed=false,frame=0,last=0,lastLine='',spokenToken=0,awarded=false,saveOK=true;
 const dialog=document.createElement('dialog');dialog.className='extra-training';dialog.classList.toggle('big-text',!!prefs.bigText);dialog.classList.toggle('reduce-motion',!!prefs.reduceMotion);dialog.setAttribute('aria-label',t(id+'Name'));document.body.append(dialog);document.body.classList.add('field-training-open');
 const factsHTML=ids=>ids.map(key=>{const f=copy('facts')[key];return `<article class="field-fact">${truthBadge('real')}<p>${esc(f.text)}</p><a href="${esc(f.url)}" target="_blank" rel="noopener">${t('source')}</a></article>`;}).join('');
 function stopVoice(){spokenToken++;try{speechSynthesis.cancel();}catch{}}
 async function speak(line){lastLine=line;stopVoice();const token=spokenToken;if(!voice||!globalThis.speechSynthesis)return;const voices=await readyVoices();if(closed||token!==spokenToken)return;try{for(const u of makeUtterances(line,voices))speechSynthesis.speak(u);}catch{}}
 function close(){if(closed)return;closed=true;stopVoice();cancelAnimationFrame(frame);document.removeEventListener('visibilitychange',hidden);window.removeEventListener('blur',blur);dialog.close();dialog.remove();document.body.classList.remove('field-training-open');onClose();}
 function button(action,label,disabled=false,extra=''){return `<button type="button" class="field-button" data-field-action="${action}" ${disabled?'disabled':''} ${extra}>${t(label)}</button>`;}
 function shell(body,phase='play'){const progress=id==='commands'?t('trainingLevel',{n:state.level+1}):t('trainingRound',{n:state.round+1});dialog.dataset.activity=id;dialog.dataset.view=phase;dialog.innerHTML=`<header class="field-header"><div><h1>${t(id+'Name')}</h1><small>${progress}</small></div><nav><button class="field-icon" data-field-action="repeat" aria-label="${t('trainingRepeat')}">↻</button><button class="field-icon" data-field-action="voice" aria-label="${t('trainingVoice')}" aria-pressed="${voice}">${voice?'🔊':'🔇'}</button><button class="field-icon" data-field-action="help" aria-label="${t('trainingHelp')}">?</button><button class="field-icon" data-field-action="close" aria-label="${t('close')}">×</button></nav></header>${body}`;}
 function focus(selector){dialog.querySelector(selector)?.focus({preventScroll:true});}
 function note(text){const node=dialog.querySelector('[data-live]');if(node)node.textContent=text;speak(text);}
 function intro(){shell(`<section class="field-reading"><span class="field-kicker">${t('trainingPipLabel')}</span><p>${t(id+'Pip')}</p>${truthBadge('game')}<p>${t(id+'Description')}</p><ul><li>${t(id+'Objective1')}</li><li>${t(id+'Objective2')}</li></ul><p class="field-small">${t(id+'Time')}</p></section><footer class="field-footer">${button('begin','trainingBegin')}${button('close','trainingBack')}</footer>`,'intro');focus('[data-field-action="begin"]');speak(t(id+'Pip'));}
 function commands(){const editing=state.phase==='editing',running=['delay','running'].includes(state.phase),level=DRIVE_LEVELS[state.level];const locations=points=>points.map(([x,y])=>t('trainingTile',{row:y+1,column:x+1})).join('; '),mapKey=t('commandMapKey',{flags:locations(level.flags),rocks:locations(level.rocks),sand:locations(level.sand)});let line=state.phase==='delay'?t('commandDelay'):state.phase==='running'?t('commandRunning'):state.phase==='failed'?t('commandFailure',{n:state.failStep+1})+' '+t('commandFail'+state.run.reason):state.ghost?t(state.ghost.success?'commandGhost':'commandGhostStop',{n:state.ghost.flags.length,step:(state.ghost.failStep??0)+1}):t('commandEditing');
  const slots=Array.from({length:12},(_,i)=>{const cmd=state.queue[i];return cmd?`<button class="drive-card ${state.selected===i?'selected':''} ${state.failStep===i?'wrong-step':''} ${state.phase==='running'&&state.step===i?'current-step':''}" data-slot="${i}" ${editing?'':'disabled'} aria-pressed="${state.selected===i}" aria-label="${t('commandSlot',{n:i+1,command:commandName(cmd)})}"><small>${i+1}</small><span aria-hidden="true">${({forward:'↑',left:'↶',right:'↷'})[cmd]}</span></button>`:`<span class="drive-card empty-card" aria-label="${t('commandEmptySlot',{n:i+1})}">${i+1}</span>`;}).join('');
  shell(`<section class="field-play drive-play"><div class="field-map"><canvas id="fieldCanvas" width="420" height="420" tabindex="0" role="img" aria-label="${t('commandsMap')}" aria-describedby="driveMapKey"></canvas><p class="field-sr-only" id="driveMapKey">${esc(mapKey)}</p><p class="map-readout" id="driveReadout"></p></div><div class="field-tools"><p class="field-live" data-live role="status">${esc(line)}</p><div class="travel-progress ${state.phase==='delay'?'':'hidden'}" role="progressbar" aria-label="${t('commandDelay')}" aria-valuemin="0" aria-valuemax="4" aria-valuenow="0"><i></i></div><p class="queue-label">${t('commandQueue',{n:state.queue.length})}<span>${t('commandPar',{n:level.par})}</span></p><div class="drive-queue" role="group" aria-label="${t('commandSelect')}">${slots}</div><div class="field-actions queue-tools">${button('earlier','commandEarlier',!editing||state.selected<=0)}${button('remove','commandRemove',!editing||state.selected<0)}${button('later','commandLater',!editing||state.selected<0||state.selected>=state.queue.length-1)}</div><div class="field-actions add-commands">${COMMANDS.map(cmd=>`<button class="field-button" data-command="${cmd}" ${!editing||state.queue.length===12?'disabled':''}>${commandName(cmd)}</button>`).join('')}</div><p class="field-small delay-honesty">${truthBadge('game')} ${t('commandDelayNote')}</p></div></section><footer class="field-footer">${state.phase==='failed'?button('edit','commandEdit'):button('simulator',state.simUsed?'commandSimUsed':'commandSimulator',!editing||state.simUsed||!state.queue.length)+button('send','commandSend',!editing||!state.queue.length)}</footer>`);
  draw();if(running)focus('#fieldCanvas');
 }
 function geology(){const rock=SAMPLE_ROCKS.find(r=>r.id===state.selected),clue=rock?t(copy('sampleRocks')[rock.id].clue):t('geologyChoose');shell(`<section class="field-play geology-play"><p class="geology-goal">${t('geologyGoal'+state.round)}</p><div class="field-map"><canvas id="fieldCanvas" width="960" height="420" tabindex="0" role="img" aria-label="${t('geologyMap')}"></canvas></div><div class="sample-buttons" role="group" aria-label="${t('geologyLens')}">${SAMPLE_ROCKS.map((r,i)=>`<button class="field-button ${state.selected===r.id?'selected':''}" data-rock="${r.id}" aria-pressed="${state.selected===r.id}">${i+1} ${sampleName(r.id)}${state.bag.includes(r.id)?' ✓':''}</button>`).join('')}</div><p class="lens-clue" data-live role="status">${rock?truthBadge(rock.simplified?'game':'real'):''} ${esc(clue)}</p><div class="field-actions keep-actions">${button('keep','geologyKeep',!rock||state.bag.includes(rock.id)||state.bag.length===3)}${button('leave','geologyLeave',!rock)}</div><p class="sample-bag" aria-live="polite"><strong>${t('geologyBag',{n:state.bag.length})}</strong><span>${state.bag.length?state.bag.map(sampleName).map(esc).join(' · '):t('geologyBagEmpty')}</span></p></section><footer class="field-footer">${button('check','geologyCheck',state.bag.length!==3)}</footer>`);draw();}
 function draw(){const canvas=dialog.querySelector('#fieldCanvas');if(!canvas)return;const c=canvas.getContext('2d');if(id==='commands'){drawDrive(c,state,DRIVE_LEVELS[state.level]);const p=state.shown??DRIVE_LEVELS[state.level].start,dir=['North','East','South','West'][p.dir];dialog.querySelector('#driveReadout').textContent=t('commandsMapReadout',{row:p.y+1,column:p.x+1,direction:t('direction'+dir),n:state.run&&['running','level-result','failed'].includes(state.phase)?state.run.path.filter(q=>q.step<state.step).reduce((set,p)=>{const i=DRIVE_LEVELS[state.level].flags.findIndex(f=>f[0]===p.x&&f[1]===p.y);if(i>=0)set.add(i);return set;},new Set()).size:0});}else drawField(c,state,SAMPLE_ROCKS);}
 function pickExplanation(p){return t(p.useful?copy('sampleRocks')[p.id].pick:p.category==='unknown'?'geologyWrongUnknown':(GEO_ROUNDS[state.round][p.category]??0)>0?'geologyExtra'+p.category[0].toUpperCase()+p.category.slice(1):'geologyWrong'+p.category[0].toUpperCase()+p.category.slice(1));}
 function roundResult(){if(id==='commands'){const r=state.results.at(-1);shell(`<section class="field-reading round-feedback"><h2>${t('commandSuccess')}</h2><div class="result-stars" aria-label="${t('trainingStars',{n:1+Number(r.efficient)+Number(r.first)})}">${'★'.repeat(1+Number(r.efficient)+Number(r.first))}</div><ul>${[['commandLevelFlagStar',true],['commandLevelCardStar',r.efficient],['commandLevelFirstStar',r.first]].map(([label,yes])=>`<li>${yes?'★':'☆'} ${t(label)}</li>`).join('')}</ul>${truthBadge('game')}<p>${t('commandPar',{n:DRIVE_LEVELS[state.level].par})}</p></section><footer class="field-footer">${button('next',state.level===2?'trainingFinish':'trainingNext')}${button('help','trainingHelp')}</footer>`,'round-result');speak(t('commandSuccess'));}
 else{const r=state.results.at(-1);shell(`<section class="field-reading round-feedback"><h2>${t('geologyRoundScore',{n:r.score})}</h2><p>${t('geologyGoal'+state.round)}</p>${r.picks.map(p=>{return `<article class="pick-note"><strong>${p.useful?'★':'☆'} ${sampleName(p.id)}</strong><p>${pickExplanation(p)}</p></article>`;}).join('')}<p class="field-small">${t('geologyContext')}</p></section><footer class="field-footer">${button('next',state.round===2?'trainingFinish':'trainingNext')}${button('help','trainingHelp')}</footer>`,'round-result');speak(t('geologyRoundScore',{n:r.score})+' '+r.picks.map(pickExplanation).join(' '));}focus('[data-field-action="next"]');}
 function result(){const r=id==='commands'?commandsResult(state):geologyResult(state);if(!awarded){awarded=true;saveOK=onFinish(r)!==false;}shell(`<section class="field-reading final-feedback"><h2>${t(r.success?'trainingDone':'trainingPractice')}</h2><div class="result-stars" aria-label="${t('trainingStars',{n:r.stars})}">${'★'.repeat(r.stars)+'☆'.repeat(3-r.stars)}</div>${r.success?`<p class="field-badge">${t('trainingBadge',{badge:t(id+'Name')})}</p><p>${t(id==='commands'?'perkCommands':'perkGeology')}</p>`:''}${r.success?`<p role="status" class="field-small">${t(saveOK?'trainingSaved':'trainingNoSave')}</p>`:''}<p class="field-small">${t(id==='commands'?'commandStarsRule':'geologyScoreRule')}</p>${truthBadge('game')}<p class="field-small">${t(id+'Rule')}</p>${truthBadge('real')}<p>${t(id+'Science')}</p><a class="field-source" href="${copy('facts')[id==='commands'?'roverPlans':'geology'].url}" target="_blank" rel="noopener">${t('source')}</a></section><footer class="field-footer">${button('close','trainingBack')}${button('again','trainingAgain')}</footer>`,'result');focus('[data-field-action="close"]');speak(t(r.success?'trainingDone':'trainingPractice'));}
 function help(){shell(`<section class="field-reading help-reading"><h2>${t('trainingHelp')}</h2>${truthBadge('game')}<p>${t(id==='commands'?'commandKeyHelp':'geologyKeyHelp')}</p><p>${t(id+'Rule')}</p>${id==='geology'?`<p>${t('geologyScoreRule')}</p>`:''}${factsHTML(id==='commands'?['roverPlans','autoNav','delay']:['geology','streambed','jezeroLayers','lavaHoles','marsSalt','marsMeteorite','rockContext'])}</section><footer class="field-footer">${button('resume','trainingResume')}</footer>`,'help');focus('[data-field-action="resume"]');}
 function pausedScreen(){shell(`<section class="field-reading"><h2>${t('pause')}</h2><p>${t('trainingPaused')}</p></section><footer class="field-footer">${button('resume','trainingResume')}${button('close','trainingBack')}</footer>`,'paused');focus('[data-field-action="resume"]');}
 function pause(){if(closed||view!=='play')return;previousView=view;view='paused';stopVoice();pausedScreen();}
 function render(){if(view==='intro')intro();else if(view==='help')help();else if(view==='result')result();else if(view==='paused')pausedScreen();else if(state.phase==='level-result'||state.phase==='round-result')roundResult();else if(id==='commands')commands();else geology();}
 function acted(focusSelector){render();if(focusSelector)focus(focusSelector);}
 dialog.addEventListener('click',e=>{const cmd=e.target.closest('[data-command]')?.dataset.command;if(cmd){if(addCommand(state,cmd))acted(`[data-command="${cmd}"]`);else note(t('commandLimit'));return;}const slot=e.target.closest('[data-slot]');if(slot&&state.phase==='editing'){state.selected=Number(slot.dataset.slot);acted(`[data-slot="${state.selected}"]`);return;}const rock=e.target.closest('[data-rock]')?.dataset.rock;if(rock){inspectRock(state,rock);acted(`[data-rock="${rock}"]`);speak(t(copy('sampleRocks')[rock].clue));return;}
 const action=e.target.closest('[data-field-action]')?.dataset.fieldAction;if(!action)return;
 if(action==='close'){close();return;}if(action==='voice'){voice=!voice;try{const p=accessPreferences();localStorage.setItem('astro-kitty-profile-v1',JSON.stringify({...p,voice}));}catch{}render();if(!voice)stopVoice();focus('[data-field-action="voice"]');return;}if(action==='repeat'){speak(lastLine||t(id+'Pip'));return;}if(action==='help'){previousView=view;view='help';stopVoice();help();return;}if(action==='resume'){last=0;view=previousView==='paused'?'play':previousView;render();return;}if(action==='begin'){view='play';render();focus('#fieldCanvas');speak(t(id==='commands'?'commandEditing':'geologyGoal0'));return;}
 if(action==='again'){close();openFieldTraining(id,{onFinish,onClose});return;}
 if(action==='next'){if(id==='commands')nextDrive(state);else nextGeology(state);if(state.phase==='complete')view='result';render();return;}
 if(id==='commands'){if(action==='send'&&sendDrive(state)){acted('#fieldCanvas');speak(t('commandDelay')+' '+t('commandDelayNote'));}else if(action==='simulator'){const r=testDrive(state);if(r){acted('[data-field-action="send"]');speak(t(r.success?'commandGhost':'commandGhostStop',{n:r.flags.length,step:(r.failStep??0)+1}));}}else if(action==='edit'&&editDrive(state))acted('[data-command="forward"]');else if(action==='remove'){removeCommand(state);acted('[data-field-action="remove"]');}else if(action==='earlier'||action==='later'){moveCommand(state,state.selected,action==='earlier'?-1:1);acted(`[data-slot="${state.selected}"]`);}}
 else if(action==='keep'){if(keepRock(state))acted('[data-field-action="leave"]');else note(t('geologyBagFull'));}else if(action==='leave'){leaveRock(state);acted('[data-rock="pebbles"]');}else if(action==='check'&&submitGeology(state)){render();}
 });
 dialog.addEventListener('keydown',e=>{if(view!=='play'||e.ctrlKey||e.metaKey||e.altKey)return;let handled=false;
 if(id==='commands'&&state.phase==='editing'){const key=e.key.toLowerCase(),cmd={f:'forward',l:'left',r:'right'}[key];if(cmd){addCommand(state,cmd);handled=true;}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){state.selected=Math.max(0,Math.min(state.queue.length-1,state.selected+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)));handled=true;}else if(e.key==='Delete'||e.key==='Backspace'){removeCommand(state);handled=true;}else if(e.key==='['||e.key===']'){moveCommand(state,state.selected,e.key==='['?-1:1);handled=true;}else if(e.key==='Enter'&&e.target.tagName==='CANVAS'){sendDrive(state);handled=true;}}
 if(id==='geology'&&state.phase==='choosing'){if(/^[1-6]$/.test(e.key)){inspectRock(state,SAMPLE_ROCKS[Number(e.key)-1].id);handled=true;}else if(e.key.toLowerCase()==='k'){keepRock(state);handled=true;}else if(e.key.toLowerCase()==='l'){leaveRock(state);handled=true;}else if(e.key==='Enter'&&e.target.tagName==='CANVAS'&&state.bag.length===3){submitGeology(state);handled=true;}}
 if(handled){e.preventDefault();e.stopPropagation();render();focus('#fieldCanvas');}
 });
 dialog.addEventListener('pointerdown',e=>{if(e.target.id!=='fieldCanvas'||id!=='geology'||state.phase!=='choosing'||view!=='play')return;const canvas=e.target,p=containPoint(e.clientX,e.clientY,canvas.getBoundingClientRect(),960,420);if(!p)return;const index=rockPositions.findIndex(([x,y])=>Math.hypot(p.x-x,p.y-y)<76);if(index>=0){inspectRock(state,SAMPLE_ROCKS[index].id);render();focus('#fieldCanvas');speak(t(copy('sampleRocks')[state.selected].clue));}});
 dialog.addEventListener('cancel',e=>{e.preventDefault();if(view==='help'||view==='paused'){view=previousView;render();}else if(view==='play')pause();else close();});
 function hidden(){if(document.hidden)pause();}function blur(){pause();}document.addEventListener('visibilitychange',hidden);window.addEventListener('blur',blur);
 function animate(now){const dt=last?Math.max(0,(now-last)/1000):0;last=now;if(view==='play'&&id==='commands'){const before=state.phase+':'+state.step;tickDrive(state,dt);if(before!==state.phase+':'+state.step){render();if(state.phase==='failed')speak(t('commandFailure',{n:state.failStep+1})+' '+t('commandFail'+state.run.reason));}const bar=dialog.querySelector('.travel-progress');if(bar){bar.setAttribute('aria-valuenow',String(Number((4-state.delay).toFixed(1))));bar.querySelector('i').style.width=(4-state.delay)/4*100+'%';}}if(!closed)frame=requestAnimationFrame(animate);}
 dialog.showModal();intro();frame=requestAnimationFrame(animate);return{close,state};
}
